<div class="narrow"><h1>نشست‌های فعال حساب</h1><p>نشست‌های مدیریت در این فهرست قرار نمی‌گیرند.</p><?php foreach($rows as $row): ?><article class="card section"><h2><?= $row['id']===$this->actor['session_id']?'این دستگاه':'نشست دیگر' ?></h2><p class="ltr"><?= $this->h($row['agent_label']) ?></p><p class="small" data-time="<?= $this->h($row['created_at']) ?>">زمان ایجاد: <?= $this->h(gmdate('Y-m-d H:i',(int)$row['created_at'])) ?> UTC</p><?= $this->start('/me/sessions/revoke') ?><input type="hidden" name="id" value="<?= $this->h($row['id']) ?>"><button class="secondary">خروج از این نشست</button></form></article><?php endforeach; ?><?= $this->start('/me/sessions/revoke-others') ?><button class="primary section">خروج از سایر نشست‌های سایت</button></form></div>
